export const getUpdateContentUrl = (slug: string,) => {




  return `/api/content/${slug}`
}

export const updateContent = async (slug: string,
    contentInput: ContentInput, options?: Parameters<typeof customFetch>[1]): Promise<Content> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Content>(getUpdateContentUrl(slug),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(contentInput)
  }
);}





export const getUpdateContentMutationKey = () => ['updateContent'] as const;

export const getUpdateContentMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateContent>>, TError,UpdateContentMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof updateContent>>, TError,UpdateContentMutationVariables, TContext> => {

const mutationKey = getUpdateContentMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateContent>>, UpdateContentMutationVariables> = (props) => {
          const {slug,data} = props ?? {};

          return  updateContent(slug,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateContentMutationResult = NonNullable<Awaited<ReturnType<typeof updateContent>>>
    export type UpdateContentMutationBody = BodyType<ContentInput>
    export type UpdateContentMutationError = ErrorType<unknown>
    export type UpdateContentMutationVariables = {slug: string;data: BodyType<ContentInput>}

    export const useUpdateContent = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateContent>>, TError,UpdateContentMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof updateContent>>,
        TError,
        UpdateContentMutationVariables,
        TContext
      > => {
      return useMutation(getUpdateContentMutationOptions(options), queryClient);
    }

